examples.code:
containers:
  - name: api
    envFrom:
      - configMapRef: { name: api-config }
      - secretRef: { name: api-secrets }
    env:
      - name: DB_PASSWORD
        valueFrom:
          secretKeyRef: { name: db-cred, key: password }

volumeMounts:
  - { name: conf, mountPath: /etc/nginx/conf.d, readOnly: true }
volumes:
  - name: conf
    configMap: { name: nginx-conf }

apiVersion: external-secrets.io/v1
kind: ExternalSecret
metadata: { name: db-cred, namespace: tienda }
spec:
  refreshInterval: 1h
  secretStoreRef: { name: aws-sm, kind: ClusterSecretStore }
  target: { name: db-cred }
  data:
    - secretKey: password
      remoteRef: { key: prod/tienda/db, property: password }
